import React, { useState } from 'react';
import { Link } from 'react-router-dom';

const videoList = [
  {
    id: '1',
    title: 'Full Stack Web Development Course 2024',
    category: 'Education',
    thumbnailUrl: 'https://img.youtube.com/vi/nu_pCVPKzTk/hqdefault.jpg',
    videoUrl: 'https://www.youtube.com/embed/nu_pCVPKzTk',
    channelName: 'freeCodeCamp.org',
    views: '1.2M'
  },
  {
    id: '2',
    title: 'Node.js & Express.js Full Course',
    category: 'Backend',
    thumbnailUrl: 'https://img.youtube.com/vi/Oe421EPjeBE/hqdefault.jpg',
    videoUrl: 'https://www.youtube.com/embed/Oe421EPjeBE',
    channelName: 'freeCodeCamp.org',
    views: '850K'
  },
  {
    id: '3',
    title: 'React.js Full Course for Beginners',
    category: 'Education',
    thumbnailUrl: 'https://img.youtube.com/vi/bMknfKXIFA8/hqdefault.jpg',
    videoUrl: 'https://www.youtube.com/embed/bMknfKXIFA8',
    channelName: 'Programming with Mosh',
    views: '2.5M'
  },
  {
    id: '4',
    title: 'MongoDB Crash Course for Beginners',
    category: 'Backend',
    thumbnailUrl: 'https://img.youtube.com/vi/ofme2o290GE/hqdefault.jpg',
    videoUrl: 'https://www.youtube.com/embed/ofme2o290GE',
    channelName: 'Traversy Media',
    views: '620K'
  },
  {
    id: '5',
    title: 'Python for Beginners - Full Course',
    category: 'Education',
    thumbnailUrl: 'https://img.youtube.com/vi/_uQrJ0TkZlc/hqdefault.jpg',
    videoUrl: 'https://www.youtube.com/embed/_uQrJ0TkZlc',
    channelName: 'Programming with Mosh',
    views: '3.1M'
  },
  {
    id: '6',
    title: 'REST API Design Best Practices',
    category: 'Backend',
    thumbnailUrl: 'https://img.youtube.com/vi/-MTSQjw5DrM/hqdefault.jpg',
    videoUrl: 'https://www.youtube.com/embed/-MTSQjw5DrM',
    channelName: 'Fireship',
    views: '410K'
  },
  {
    id: '7',
    title: 'Learn CSS Grid & Flexbox in 20 Minutes',
    category: 'UI/UX',
    thumbnailUrl: 'https://img.youtube.com/vi/rg7Fvvl3taU/hqdefault.jpg',
    videoUrl: 'https://www.youtube.com/embed/rg7Fvvl3taU',
    channelName: 'Web Dev Simplified',
    views: '950K'
  },
  {
    id: '8',
    title: 'Figma UI Design Tutorial for Beginners',
    category: 'UI/UX',
    thumbnailUrl: 'https://img.youtube.com/vi/c9Wg6Cb_YlU/hqdefault.jpg',
    videoUrl: 'https://www.youtube.com/embed/c9Wg6Cb_YlU',
    channelName: 'DesignCourse',
    views: '780K'
  },
  {
    id: '9',
    title: 'Docker Tutorial for Beginners',
    category: 'DevOps',
    thumbnailUrl: 'https://img.youtube.com/vi/pTFZFxd4hOI/hqdefault.jpg',
    videoUrl: 'https://www.youtube.com/embed/pTFZFxd4hOI',
    channelName: 'TechWorld with Nana',
    views: '1.8M'
  },
  {
    id: '10',
    title: 'Git and GitHub Tutorial for Beginners',
    category: 'DevOps',
    thumbnailUrl: 'https://img.youtube.com/vi/RGOj5yH7evk/hqdefault.jpg',
    videoUrl: 'https://www.youtube.com/embed/RGOj5yH7evk',
    channelName: 'freeCodeCamp.org',
    views: '2.1M'
  },
  {
    id: '11',
    title: 'JavaScript DOM Manipulation Course',
    category: 'Education',
    thumbnailUrl: 'https://img.youtube.com/vi/5fb2aPlgoys/hqdefault.jpg',
    videoUrl: 'https://www.youtube.com/embed/5fb2aPlgoys',
    channelName: 'Traversy Media',
    views: '540K'
  },
  {
    id: '12',
    title: 'Kubernetes Course - Full Beginners Tutorial',
    category: 'DevOps',
    thumbnailUrl: 'https://img.youtube.com/vi/X48VuDVv0do/hqdefault.jpg',
    videoUrl: 'https://www.youtube.com/embed/X48VuDVv0do',
    channelName: 'TechWorld with Nana',
    views: '1.4M'
  }
];

function Home({ searchTerm }) {
  const [category, setCategory] = useState('All');

  const filteredVideos = videoList.filter((video) => {
    const matchesCategory = category === 'All' || video.category === category;
    const matchesSearch = !searchTerm || video.title.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  return (
    <div className="page-layout">
      <aside className="sidebar">
        <h3>Categories</h3>
        {['All', 'Education', 'Backend', 'UI/UX', 'DevOps'].map((cat) => (
          <button
            key={cat}
            className={category === cat ? 'active' : ''}
            onClick={() => setCategory(cat)}
          >
            {cat}
          </button>
        ))}
      </aside>
      <main className="video-section">
        <div className="video-grid">
          {filteredVideos.map((video) => (
            <Link key={video.id} to={`/video/${video.id}`} className="card-link">
              <div className="card">
                <img src={video.thumbnailUrl} alt={video.title} />
                <h4>{video.title}</h4>
                <p>{video.channelName} • {video.views} views</p>
              </div>
            </Link>
          ))}
        </div>
      </main>
    </div>
  );
}

export default Home;
